package com.medcore.backend.api.infraestructura.camas;import jakarta.persistence.*;
@Entity@Table(name="camas")public class Cama{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(nullable=false,length=20)private String numero;@Column(name="habitacion_id",nullable=false)private Long habitacionId;@Enumerated(EnumType.STRING)@Column(nullable=false,length=20)private EstadoCama estado;@PrePersist void init(){if(estado==null)estado=EstadoCama.DISPONIBLE;}public Long getId(){return id;}public void setId(Long v){id=v;}public String getNumero(){return numero;}public void setNumero(String v){numero=v;}public Long getHabitacionId(){return habitacionId;}public void setHabitacionId(Long v){habitacionId=v;}public EstadoCama getEstado(){return estado;}public void setEstado(EstadoCama v){estado=v;}}
